def snap(name, where, lvl, lines, checked):
    content = [P(name, snapname), P(where + "  ·  " + lvl, stattag)] + [P(l, snapline) for l in lines] + [P("<b>The feat, checked.</b> " + checked, snapline)]
    t = Table([[content]], colWidths=[W]); t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),PARCH),("LINEBEFORE",(0,0),(0,-1),2.5,GREEN),("LEFTPADDING",(0,0),(-1,-1),10),("RIGHTPADDING",(0,0),(-1,-1),10),("TOPPADDING",(0,0),(-1,-1),7),("BOTTOMPADDING",(0,0),(-1,-1),7)]))
    return KeepTogether([t, Spacer(1,7)])
S.append(snap("The Red Dragon", "before the show; the flashbacks · ages 17 to 24", "Levels 1–9 · Monk 1–6, Rogue 1–3", ["Dex 18, Con 15 · <b>AC</b> 16 · <b>HP</b> up to 72 · fists 1d6+4, five a turn from level 5 · Stunning Strike · the Jericho with Sneak Attack from level 7 · Assassinate from level 9"], "A syndicate hitman is an Assassin with a pistol: advantage on the first round against anyone who hasn't moved, a Sneak Attack with the rogue level on top, and a Stunning Strike for the one who has. The eye is a wound the sheet does not roll for. Faking his death is a Deception check he was always going to pass, because the man checking was Vicious."))
S.append(snap("Asimov, and the window", "Asteroid Blues; Ballad of Fallen Angels · 2071", "Levels 10–14 · Rogue 4–6, Monk 7–8", ["<b>AC</b> 17 · <b>HP</b> 95 → 128 · Uncanny Dodge, Evasion · Tough"], "Asimov on Red Eye is a Thug under Haste with a knife: three attacks, 40 feet of speed, and Spike loses the brawl because the sheet says a man with two attacks and a 2d10+5 Flurry doesn't beat a man with four; he wins the fight with the pistol, which is Sneak Attack from behind a car. The cathedral is Vicious, CR 13 with a katana and a sword saint's AC, and it ends with Spike shot, cut, and out a stained-glass window: a fall of 40 feet is 4d6, Evasion is not for falls, and the reason he lives is three Luck Points on the Con save in the hospital and the thing the sheet calls Nine Lives. The show calls it a dream he never woke up from."))
S.append(snap("Pierrot le Fou", "session 20 · the man who can't be hit", "Level 16 · Monk 10 / Rogue 6", ["<b>HP</b> 145 · Flurry of three · Heightened Focus"], "Mad Pierrot is a CR 15 with a flying speed, a personal force field that eats every attack (immunity to all damage from attacks, as written), and a Gatling gun. Spike cannot hurt him and the sheet agrees: five strikes a turn into immunity is zero. He wins with a knife thrown into the one place the field doesn't cover, a called shot at disadvantage for 1d4+5, and the fact that Pierrot is afraid of cats. The DM is allowed to say that. The show did."))
S.append(snap("Vincent", "Knockin' on Heaven's Door · the film", "Level 17 · Monk 11 / Rogue 6", ["<b>HP</b> 157 · Martial Arts d10 · Fleet Step"], "Vincent Volaju is a CR 14 special-forces ghost who can't be killed by the thing he's carrying and fights with a knife at Spike's own level. The first fight on the monorail is a loss: Spike takes a knife in the gut (a crit with Sneak Attack, call it 30), goes into the water, and lives on Luck. The second, on the tower in the rain, is the same two men with Spike having seen every move once: advantage on Insight from the eye, Stop-Hit on the misses, Stunning Strike when it lands. Vincent lets Elektra finish it. That is the one fight on this sheet he was given rather than won, and he knows it."))
S.append(snap("The Real Folk Blues", "sessions 25 and 26 · the end", "Level 20 · Monk 14 / Rogue 6", ["The headline block: AC 17, 183 HP, six Luck Points, Nine Lives, the grenades"], "The Red Dragon tower is forty Guards and Veterans (CR 1/8 to CR 3) across a lobby, an elevator and a stairwell, with one man coming the other way. Grenades for the lobby (3d6 in ten feet, three of them), the Jericho with Sneak Attack for the hallways, hands for anything that closes. He takes every hit that lands: by the top he is under 50 and has spent the luck. Vicious is a CR 13 katana master with the same AC he has and the same number of attacks; the exchange is one Stunning Strike that doesn't land, one Sneak Attack that does, and a slash across the chest that Nine Lives turns into 1 hit point. He walks down the stairs, points a finger at the men who are left, says the word, and the sheet stops there, because the show does."))
